mapper.insert:
INSERT INTO TB_PBANC_CLCT_HSTRY (
  PBANC_SN, CLCT_SEQ, PBANC_STEP_CD, PBANC_NO, BID_PBANC_CYCL,
  PBANC_TYPE_CD, ALTMNT_BGT_AMT, BID_DDLN_DT, OPENG_DT, API_RSPNS_CN
) VALUES (
  #{pbancSn}, #{clctSeq}, #{pbancStepCd}, #{pbancNo}, #{bidPbancCycl},
  #{pbancTypeCd}, #{altmntBgtAmt}, #{bidDdlnDt}, #{opengDt}, #{apiRspnsCn}
)

INSERT INTO TB_PBANC_PRCS_HSTRY (
  PBANC_SN, TRGT_TEAM_SN, PRCS_SE_CD, PRCS_RSN, PRCR_ID
) VALUES (
  #{pbancSn}, #{trgtTeamSn}, #{prcsSeCd}, #{prcsRsn}, #{prcrId}
)

mapper.select:
SELECT COUNT(*)
  FROM TB_BID_PBANC
 WHERE ORDER_PLAN_NO = #{orderPlanNo}

mapper.insert:
INSERT INTO TB_ATCH_FILE (
  PBANC_SN, FILE_SE_CD, VER_NO, ORGNL_FILE_NM, ORGNL_URL, FILE_SZ, FILE_EXTN_NM, RGTR_ID
) VALUES (
  #{pbancSn}, #{fileSeCd}, NVL(#{verNo}, '1'), #{orgnlFileNm}, #{orgnlUrl}, #{fileSz}, #{fileExtnNm},
  NVL(#{rgtrId}, (SELECT RGTR_ID FROM TB_BID_PBANC WHERE PBANC_SN = #{pbancSn}))
)

mapper.select:
SELECT NVL(MAX(CLCT_SEQ), 0) + 1
  FROM TB_PBANC_CLCT_HSTRY
 WHERE PBANC_SN = #{pbancSn}

mapper.insert:
INSERT INTO TB_CLCT_LOG (
  PBANC_SN, EXCN_SE_CD, EXCTR_ID, CLCT_RSLT_CD, ERR_MSG_CN
) VALUES (
  #{pbancSn}, #{excnSeCd}, #{exctrId}, #{clctRsltCd}, #{errMsgCn}
)

mapper.update:
UPDATE TB_BID_PBANC
   SET PBANC_STTS_CD = #{toSttsCd},
       RTRN_SE_CD    = NULL
 WHERE PBANC_SN = #{pbancSn}
   AND PBANC_STTS_CD = #{fromSttsCd}

mapper.select:
SELECT COUNT(*)
  FROM TB_BID_PBANC P
  JOIN TB_USER U ON U.TEAM_SN = P.SPRVSN_TEAM_SN
 WHERE P.PBANC_SN = #{pbancSn}
   AND U.USER_ID = #{userId}
   AND U.AUTHRT_CD = #{leaderCd}

mapper.update:
UPDATE TB_BID_PBANC
   SET PBANC_STTS_CD = #{toSttsCd}
 WHERE PBANC_SN = #{pbancSn}
   AND SPRVSN_TEAM_SN = #{teamSn}
   AND PBANC_STTS_CD = #{fromSttsCd}

UPDATE TB_BID_PBANC
   SET PBANC_STTS_CD  = #{toSttsCd},
       RTRN_SE_CD     = #{rtrnSeCd},
       SPRVSN_TEAM_SN = NULL
 WHERE PBANC_SN = #{pbancSn}
   AND SPRVSN_TEAM_SN = #{teamSn}
   AND PBANC_STTS_CD = #{fromSttsCd}
